# we'll define a function to calculate the the log of the factorial of n
import numpy as np
def factorial(n):
    assert type(n) == int and n>0, "n must be an integer and greater than zero"
    factorial = n
    while n>1:
        factorial = factorial*(n-1); n = n-1
    return factorial
def log_factorial(n):
    return np.log(float(factorial(n)))
